using MovieInfoBackend.DataModels;
using Xunit.Abstractions;

public class TmdbConfigurationDataModelTests
{
    private string tmdbHttpClientConfigurationCountriesResponse;
    private string tmdbHttpClientConfigurationLanguagesResponse;

    public TmdbConfigurationDataModelTests(ITestOutputHelper output)
    {
        // Arrange

        string testCountriesDataFilename = "TmdbHttpClientConfigurationCountriesResponse.json";
        string testLanguagesDataFilename = "TmdbHttpClientConfigurationLanguagesResponse.json";

        using (StreamReader sr = File.OpenText($"../../../TestData/{testCountriesDataFilename}"))
        {
            tmdbHttpClientConfigurationCountriesResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientConfigurationCountriesResponse))
        {
            throw new ArgumentException($"{testCountriesDataFilename} is not valid test data.");
        }

        using (StreamReader sr = File.OpenText($"../../../TestData/{testLanguagesDataFilename}"))
        {
            tmdbHttpClientConfigurationLanguagesResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientConfigurationLanguagesResponse))
        {
            throw new ArgumentException($"{testLanguagesDataFilename} is not valid test data.");
        }
    }

    [Fact]
    public void GetModelFromResponse_ValidResponse_ReturnsValidModels()
    {
        // Act / Assert
        
        // Countries

        TmdbConfigurationCountriesResponseDataModel? tvConfigurationCountriesResponse = TmdbHttpClient.GetConfigurationCountriesModelFromResponse(tmdbHttpClientConfigurationCountriesResponse);
        Assert.NotNull(tvConfigurationCountriesResponse);
        TmdbConfigurationCountryDataModel[] countries = tvConfigurationCountriesResponse.Countries;
        Assert.NotEmpty(countries);
        TmdbConfigurationCountryDataModel firstCountry = countries[0];
        TmdbConfigurationCountryDataModel lastCountry = countries[countries.Length - 1];
        Assert.False(String.IsNullOrWhiteSpace(firstCountry.Iso31661), "First country Iso31661 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCountry.EnglishName), "First country EnglishName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCountry.NativeName), "First country NativeName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(lastCountry.Iso31661), "Last country Iso31661 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(lastCountry.EnglishName), "Last country EnglishName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(lastCountry.NativeName), "Last country NativeName must not be empty");
        TmdbConfigurationCountriesResponseDataModel.ConfigurationCountriesDictionary? tvConfigurationCountriesDictionary = tvConfigurationCountriesResponse.GetConfigurationCountriesDictionary();
        Assert.NotNull(tvConfigurationCountriesDictionary);
        Assert.Equal(firstCountry.EnglishName, tvConfigurationCountriesDictionary.iso31661ToEnglishCountryNameDictionary[firstCountry.Iso31661]);
        Assert.Equal(lastCountry.EnglishName, tvConfigurationCountriesDictionary.iso31661ToEnglishCountryNameDictionary[lastCountry.Iso31661]);

        // Languages

        TmdbConfigurationLanguagesResponseDataModel? tvConfigurationLanguagesResponse = TmdbHttpClient.GetConfigurationLanguagesModelFromResponse(tmdbHttpClientConfigurationLanguagesResponse);
        Assert.NotNull(tvConfigurationLanguagesResponse);
        TmdbConfigurationLanguageDataModel[] languages = tvConfigurationLanguagesResponse.Languages;
        Assert.NotEmpty(languages);
        TmdbConfigurationLanguageDataModel firstLanguage = languages[0];
        TmdbConfigurationLanguageDataModel lastLanguage = languages[languages.Length - 1];
        Assert.False(String.IsNullOrWhiteSpace(firstLanguage.Iso6391), "First language Iso6391 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstLanguage.EnglishName), "First language EnglishName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstLanguage.Name), "First language Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(lastLanguage.Iso6391), "Last language Iso6391 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(lastLanguage.EnglishName), "Last language EnglishName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(lastLanguage.Name), "Last language Name must not be empty");
        TmdbConfigurationLanguagesResponseDataModel.ConfigurationLanguagesDictionary? tvConfigurationLanguagesDictionary = tvConfigurationLanguagesResponse.GetConfigurationLanguagesDictionary();
        Assert.NotNull(tvConfigurationLanguagesDictionary);
        Assert.Equal(firstLanguage.EnglishName, tvConfigurationLanguagesDictionary.iso6391ToEnglishLanguageNameDictionary[firstLanguage.Iso6391]);
        Assert.Equal(lastLanguage.EnglishName, tvConfigurationLanguagesDictionary.iso6391ToEnglishLanguageNameDictionary[lastLanguage.Iso6391]);
    }

